def parse_il_date(value):
    if not value:
        return None
    return datetime.strptime(value, "%d/%m/%Y").date()


def normalized_status(value):
    return {
        "לביצוע": "open",
        "בטיפול": "in_progress",
        "ממתין לאישור": "waiting_approval",
        "הושלם": "done",
        "בוטל": "cancelled",
    }[value]


def confirmed_due_date(row):
    return None if len(row) > 11 and row[11] == "proposed" else parse_il_date(row[6])


def import_rows(dry_run=False):
    app = create_app()
    created = updated = unchanged = 0
    with app.app_context():
        db.session.rollback()
        try:
            for index, row in enumerate(ROWS, start=1001):
                phase, title, asset, case_no, forms, owner, target, status_label, notes, completed, domain, *extra = row
                proposed = bool(extra and extra[0] == "proposed")
                marker = f"ייבוא טבלת מעקב כבאות והצלה: {SOURCE} | גרסה: {VERSION} | שורה מקורית: {index}"
                task = Task.query.filter(Task.description.contains(marker)).first()
                confirmed_due = confirmed_due_date(row)
                actual_done = parse_il_date(completed)
                metadata = [
                    f"שלב / שבוע: {phase}",
                    f"נכס רלוונטי: {asset}",
                    f"מספר תיק: {case_no}",
                    f"מספר טופס להגשה: {forms}",
                    f"גורם אחראי: {owner}",
                    f"תאריך יעד לביצוע: {target}",
                    f"תאריך יעד מאושר: {'לא — מועד מוצע לאישור' if proposed else 'כן' if target else 'לא הוגדר'}",
                    f"סטטוס מקור: {status_label}",
                    f"הערות ודגשים: {notes}",
                    f"תאריך ביצוע בפועל: {completed}",
                    f"תחום: {domain}",
                    f"התראת מועד: {'הושלם' if status_label == 'הושלם' else 'ממתין לאישור יעד' if proposed else 'מחושב בזמן אמת'}",
                    marker,
                ]
                description = "\n".join(metadata)
                values = {
                    "title": title,
                    "description": description,
                    "assignee": owner,
                    "priority": "urgent" if "קריטי!" in notes else "normal",
                    "status": normalized_status(status_label),
                    "due_date": confirmed_due,
                    "completed_at": datetime.combine(actual_done, datetime.min.time()) if actual_done else (
                        task.completed_at if task and task.status == "done" else None
                    ),
                }
                if task:
                    changed = any(getattr(task, key) != value for key, value in values.items())
                    if changed:
                        for key, value in values.items():
                            setattr(task, key, value)
                        updated += 1
                    else:
                        unchanged += 1
                else:
                    task = Task(**values)
                    db.session.add(task)
                    created += 1
            if dry_run:
                db.session.rollback()
            else:
                db.session.commit()
        except Exception:
            db.session.rollback()
            LOG.exception("Work-plan sync failed; transaction rolled back")
            raise
    result = {
        "source_rows": len(ROWS),
        "created": created,
        "updated": updated,
        "unchanged": unchanged,
        "errors": 0,
        "dry_run": dry_run,
        "version": VERSION,
    }
    LOG.info("Sync result: %s", result)
    return result


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--dry-run", action="store_true")
    args = parser.parse_args()
    print(import_rows(dry_run=args.dry_run))
